# Generated by build.py from recipe.yml for recipe http-limit-download-speed. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
cmd /c 'dd if=/dev/zero of=site/big.bin bs=1000 count=100'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o big.bin --limit-rate 25k -w "%{size_download} bytes at %{speed_download} bytes/s in %{time_total} s\n" http://127.0.0.1:8080/big.bin } finally { Stop-Process $server0 }
